using Avalonia;
using Avalonia.Controls;
using Avalonia.Threading;
using Avalonia.VisualTree;
using VisualRelay.App.ViewModels;
using VisualRelay.App.Views;
using VisualRelay.App.Views.Controls;
using VisualRelay.Domain;

namespace VisualRelay.Tests;

[Collection("Headless")]
public sealed class TierVisibilityProbeTests
{
    [AvaloniaFact]
    public void Probe_TierTextBlock_AtRestAndLong()
    {
        var viewModel = new MainWindowViewModel(new DictionaryEnvironmentAccessor { ["XDG_CONFIG_HOME"] = Path.GetTempPath() });

        var window = new MainWindow
        {
            DataContext = viewModel,
            Width = 1440,
            Height = 900
        };
        window.Show();
        Dispatcher.UIThread.RunJobs();

        var stage7 = viewModel.Stages.Single(s => s.Number == 7);
        // At-rest tier for stage 7 is "frontier".
        var atRest = FindTextBlockWithText(window, "frontier");
        Report("at-rest frontier", atRest);

        // Long combo on stage 11.
        var stage11 = viewModel.Stages.Single(s => s.Number == 11);
        stage11.ApplyMetric(new StageRunMetric(
            StageNumber: 11, StageName: "Fix-verify", Tier: "balanced",
            Model: "hf-qwen3-coder-next", Timestamp: DateTimeOffset.UtcNow,
            DurationSeconds: 120, CostUsd: 0.0042, Priced: true, PromptTokens: 0,
            CachedTokens: 0, OutputTokens: 0, CacheWriteTokens: 0,
            ReportPath: "/tmp/r.md", TraceDirectory: null, Turns: 9));
        Dispatcher.UIThread.RunJobs();

        var longBlock = FindTextBlockWithText(window, "balanced · hf-qwen3-coder-next");
        Report("long tier block", longBlock);
    }

    private static void Report(string label, TextBlock? tb)
    {
        if (tb is null)
        {
            Console.WriteLine($"[{label}] NOT FOUND");
            return;
        }

        Console.WriteLine($"[{label}] Text='{tb.Text}' Bounds={tb.Bounds} "
            + $"Desired={tb.DesiredSize} IsVisible={tb.IsVisible} "
            + $"IsEffectivelyVisible={tb.IsEffectivelyVisible}");
        var p = tb.Parent;
        while (p is not null)
        {
            if (p is Control c)
            {
                Console.WriteLine($"  parent {p.GetType().Name} Bounds={c.Bounds} "
                    + $"IsVisible={c.IsVisible} ClipToBounds={(c as Border)?.ClipToBounds}");
            }
            else
            {
                Console.WriteLine($"  parent {p.GetType().Name}");
            }
            p = p.Parent;
        }
    }

    private static TextBlock? FindTextBlockWithText(Visual root, string text) =>
        root.GetVisualDescendants()
            .OfType<StageBoard>()
            .SelectMany(board => board.GetVisualDescendants().OfType<TextBlock>())
            .FirstOrDefault(tb => tb.Text == text);
}

using Avalonia;
using Avalonia.Controls;
using Avalonia.Threading;
using Avalonia.VisualTree;
using VisualRelay.App.ViewModels;
using VisualRelay.App.Views;
using VisualRelay.App.Views.Controls;
using VisualRelay.Domain;

namespace VisualRelay.Tests;

[Collection("Headless")]
public sealed class TierVisibilityProbeTests
{
    [AvaloniaFact]
    public void Probe_TierTextBlock_AtRestAndLong()
    {
        var viewModel = new MainWindowViewModel(new DictionaryEnvironmentAccessor { ["XDG_CONFIG_HOME"] = Path.GetTempPath() });

        var window = new MainWindow
        {
            DataContext = viewModel,
            Width = 1440,
            Height = 900
        };
        window.Show();
        Dispatcher.UIThread.RunJobs();

        var lines = new System.Text.StringBuilder();
        var stage7 = viewModel.Stages.Single(s => s.Number == 7);
        var atRest = FindTextBlockWithText(window, "frontier");
        lines.AppendLine(Describe("at-rest frontier", atRest));

        var stage11 = viewModel.Stages.Single(s => s.Number == 11);
        stage11.ApplyMetric(new StageRunMetric(
            StageNumber: 11, StageName: "Fix-verify", Tier: "balanced",
            Model: "hf-qwen3-coder-next", Timestamp: DateTimeOffset.UtcNow,
            DurationSeconds: 120, CostUsd: 0.0042, Priced: true, PromptTokens: 0,
            CachedTokens: 0, OutputTokens: 0, CacheWriteTokens: 0,
            ReportPath: "/tmp/r.md", TraceDirectory: null, Turns: 9));
        Dispatcher.UIThread.RunJobs();

        var longBlock = FindTextBlockWithText(window, "balanced · hf-qwen3-coder-next");
        lines.AppendLine(Describe("long tier block", longBlock));

        var probePath = Path.Combine(AppContext.BaseDirectory, "tier_probe.txt");
        File.WriteAllText(probePath, lines.ToString());
        File.WriteAllText(Path.Combine(Path.GetTempPath(), "tier_probe.txt"), lines.ToString());
    }

    private static string Describe(string label, TextBlock? tb)
    {
        if (tb is null)
            return $"[{label}] NOT FOUND";
        var sb = new System.Text.StringBuilder();
        sb.AppendLine($"[{label}] Text='{tb.Text}' Bounds={tb.Bounds} Desired={tb.DesiredSize} "
            + $"IsVisible={tb.IsVisible} IsEffectivelyVisible={tb.IsEffectivelyVisible}");
        var p = tb.Parent;
        while (p is not null)
        {
            if (p is Control c)
                sb.AppendLine($"  parent {p.GetType().Name} Bounds={c.Bounds} IsVisible={c.IsVisible} ClipToBounds={(c as Border)?.ClipToBounds}");
            else
                sb.AppendLine($"  parent {p.GetType().Name}");
            p = p.Parent;
        }
        return sb.ToString();
    }

    private static TextBlock? FindTextBlockWithText(Visual root, string text) =>
        root.GetVisualDescendants()
            .OfType<StageBoard>()
            .SelectMany(board => board.GetVisualDescendants().OfType<TextBlock>())
            .FirstOrDefault(tb => tb.Text == text);
}

