import Foundation
import Vision
import AppKit

let args = CommandLine.arguments
guard args.count > 1, let img = NSImage(contentsOfFile: args[1]),
      let cg = img.cgImage(forProposedRect: nil, context: nil, hints: nil) else {
    FileHandle.standardError.write("usage: ocr <png>\n".data(using: .utf8)!)
    exit(1)
}

let request = VNRecognizeTextRequest()
request.recognitionLevel = .accurate
request.usesLanguageCorrection = false
let handler = VNImageRequestHandler(cgImage: cg, options: [:])
try handler.perform([request])

let results = (request.results ?? []).sorted {
    if abs($0.boundingBox.midY - $1.boundingBox.midY) > 0.02 { return $0.boundingBox.midY > $1.boundingBox.midY }
    return $0.boundingBox.minX < $1.boundingBox.minX
}
for obs in results {
    if let cand = obs.topCandidates(1).first {
        let b = obs.boundingBox
        // Vision origin is bottom-left; convert to top-left pixel coords
        let x = b.minX * Double(cg.width)
        let y = (1 - b.maxY) * Double(cg.height)
        let w = b.width * Double(cg.width)
        let h = b.height * Double(cg.height)
        print(String(format: "%@\t@(%.0f,%.0f %.0fx%.0f)", cand.string, x, y, w, h))
    }
}
